package skin

import (
	"strings"

	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/bubbles/textinput"
	"github.com/charmbracelet/lipgloss"
)

// chatPalette is the resolved set of semantic transcript-role colors for a
// skin. Every field is sourced from HermesSkinColors so that switching the
// active skin re-themes the whole chat surface; nothing here is a hardcoded
// palette (ccx-go's flat styles.go is a naming donor only, not its colors).
type ChatPalette struct {
	User       string
	Assistant  string
	ToolName   string
	ToolOutput string
	Error      string
	Prompt     string
	Separator  string
	Status     string
}

// SkinStyles is the shared Bubble Tea/Lip Gloss style set for all Gormes TUI
// surfaces. Chat, admin, and setup wizard code should derive local component
// chrome from this seam instead of rebuilding token mappings independently.
type SkinStyles struct {
	User         lipgloss.Style
	Assistant    lipgloss.Style
	ToolName     lipgloss.Style
	ToolOutput   lipgloss.Style
	Error        lipgloss.Style
	Prompt       lipgloss.Style
	Placeholder  lipgloss.Style
	Text         lipgloss.Style
	Selected     lipgloss.Style
	Normal       lipgloss.Style
	Dim          lipgloss.Style
	Separator    lipgloss.Style
	Status       lipgloss.Style
	Title        lipgloss.Style
	Label        lipgloss.Style
	Accent       lipgloss.Style
	BannerBorder lipgloss.Style
	BannerAccent lipgloss.Style
	BannerDim    lipgloss.Style
	ActivePill   lipgloss.Style
	Good         lipgloss.Style
	Warn         lipgloss.Style
	Bad          lipgloss.Style
	Critical     lipgloss.Style
	Cursor       lipgloss.Style
	FocusLine    lipgloss.Style
}

// NormalizeStyleSkin returns the default Hermes/Gormes skin when callers pass
// a zero-value skin. Subpackages use this to keep fallback policy in one place.
func NormalizeStyleSkin(skin HermesSkin) HermesSkin {
	if strings.TrimSpace(skin.Name) == "" {
		return DefaultHermesSkin()
	}
	return skin
}

func ChatPaletteFor(skin HermesSkin) ChatPalette {
	skin = NormalizeStyleSkin(skin)
	c := skin.Colors
	return ChatPalette{
		User:       c.UILabel,
		Assistant:  c.SessionBorder,
		ToolName:   c.UIAcent,
		ToolOutput: c.BannerDim,
		Error:      c.UIError,
		Prompt:     c.Prompt,
		Separator:  c.SessionBorder,
		Status:     c.UILabel,
	}
}

func Foreground(hex string) lipgloss.Style {
	return lipgloss.NewStyle().Foreground(lipgloss.Color(hex))
}

func RenderStyle(enabled bool, style lipgloss.Style, value string) string {
	if !enabled {
		return value
	}
	return style.Render(value)
}

// SkinStylesFor resolves the shared semantic style set from a skin. It is the
// common source for chat transcript styles, admin shell chrome, setup wizard
// inputs, and future Bubble Tea overlays.
func SkinStylesFor(skin HermesSkin) SkinStyles {
	skin = NormalizeStyleSkin(skin)
	p := ChatPaletteFor(skin)
	c := skin.Colors
	return SkinStyles{
		User:         Foreground(p.User).Bold(true),
		Assistant:    Foreground(p.Assistant),
		ToolName:     Foreground(p.ToolName).Bold(true),
		ToolOutput:   Foreground(p.ToolOutput),
		Error:        Foreground(p.Error).Bold(true),
		Prompt:       Foreground(p.Prompt).Bold(true),
		Placeholder:  Foreground(c.Placeholder).Italic(true),
		Text:         Foreground(c.BannerText),
		Selected:     Foreground(c.UIAcent).Bold(true),
		Normal:       Foreground(c.BannerText),
		Dim:          Foreground(c.StatusBarDim),
		Separator:    Foreground(p.Separator),
		Status:       Foreground(c.StatusBarText).Background(lipgloss.Color(c.StatusBarBackground)),
		Title:        Foreground(c.BannerTitle).Bold(true),
		Label:        Foreground(c.UILabel).Bold(true),
		Accent:       Foreground(c.UIAcent).Bold(true),
		BannerBorder: Foreground(c.BannerBorder),
		BannerAccent: Foreground(c.BannerAccent).Bold(true),
		BannerDim:    Foreground(c.BannerDim),
		ActivePill:   Foreground(c.StatusBarBackground).Background(lipgloss.Color(c.UIAcent)).Bold(true),
		Good:         Foreground(c.StatusBarGood).Bold(true),
		Warn:         Foreground(c.StatusBarWarn).Bold(true),
		Bad:          Foreground(c.StatusBarBad).Bold(true),
		Critical:     Foreground(c.StatusBarCritical).Bold(true),
		Cursor:       Foreground(c.UIAcent).Reverse(true),
		FocusLine:    Foreground(c.BannerText).Background(lipgloss.Color(c.StatusBarBackground)),
	}
}

// chatStyles holds the lipgloss style for each semantic transcript role,
// derived from the active HermesSkin. view.go renders every role/chrome
// element through these named styles instead of scattered inline
// lipgloss.NewStyle calls.
type ChatStyles struct {
	User       lipgloss.Style
	Assistant  lipgloss.Style
	ToolName   lipgloss.Style
	ToolOutput lipgloss.Style
	Error      lipgloss.Style
	Prompt     lipgloss.Style
	Separator  lipgloss.Style
	Status     lipgloss.Style
}

func ChatStylesFor(skin HermesSkin) ChatStyles {
	styles := SkinStylesFor(skin)
	return ChatStyles{
		User:       styles.User,
		Assistant:  styles.Assistant,
		ToolName:   styles.ToolName,
		ToolOutput: styles.ToolOutput,
		Error:      styles.Error,
		Prompt:     styles.Prompt,
		Separator:  styles.Separator,
		Status:     styles.Label,
	}
}

func ApplyTextareaSkin(input *textarea.Model, skin HermesSkin) {
	if input == nil {
		return
	}
	styles := SkinStylesFor(skin)

	input.FocusedStyle.Prompt = styles.Prompt
	input.BlurredStyle.Prompt = styles.Placeholder
	input.FocusedStyle.Placeholder = styles.Placeholder
	input.BlurredStyle.Placeholder = styles.Placeholder
	input.FocusedStyle.Text = styles.Text
	input.BlurredStyle.Text = styles.Text
	input.FocusedStyle.CursorLine = styles.FocusLine
	input.BlurredStyle.CursorLine = lipgloss.NewStyle()
	input.Cursor.Style = styles.Cursor
	input.Cursor.TextStyle = styles.Text
}

func ApplyTextInputSkin(input *textinput.Model, skin HermesSkin) {
	if input == nil {
		return
	}
	styles := SkinStylesFor(skin)
	input.PromptStyle = styles.Prompt
	input.PlaceholderStyle = styles.Placeholder
	input.TextStyle = styles.Text
	input.Cursor.Style = styles.Cursor
	input.Cursor.TextStyle = styles.Text
}

package skin

// WelcomePalette is the small set of colors the welcome panel needs. It is
// derived from the active HermesSkin's banner tokens so every built-in skin
// keeps theming the panel.
type WelcomePalette struct {
	Border string
	Title  string
	Accent string
	Dim    string
}

// WelcomePaletteFor returns the welcome-panel color tokens for a skin.
func WelcomePaletteFor(skin HermesSkin) WelcomePalette {
	skin = NormalizeStyleSkin(skin)
	return WelcomePalette{
		Border: skin.Colors.BannerBorder,
		Title:  skin.Colors.BannerTitle,
		Accent: skin.Colors.BannerAccent,
		Dim:    skin.Colors.BannerDim,
	}
}

// BannerLogoColors returns the per-line color sequence for the full Gormes
// ASCII logo, derived from the active skin's banner tokens.
func BannerLogoColors(skin HermesSkin) []string {
	skin = NormalizeStyleSkin(skin)
	c := skin.Colors
	return []string{c.BannerBorder, c.BannerAccent, c.BannerTitle, c.BannerText, c.BannerTitle, c.BannerAccent}
}

// BannerCaduceusColors returns the per-band color sequence for the compact
// caduceus art, derived from the active skin's banner tokens.
func BannerCaduceusColors(skin HermesSkin) []string {
	skin = NormalizeStyleSkin(skin)
	c := skin.Colors
	return []string{c.BannerBorder, c.BannerAccent, c.BannerTitle, c.BannerTitle, c.BannerAccent, c.BannerDim}
}

package skin

import "strings"

type Request struct {
	Name      string
	SessionID string
}

type Result struct {
	Name string
}

type ConfigFunc func(Request) (Result, error)

type SlashResult struct {
	Name          string
	AcceptedName  string
	Apply         bool
	Body          string
	StatusMessage string
	Err           error
}

func HandleSlash(input string, sessionID string, configure ConfigFunc) SlashResult {
	name := SlashName(input)
	if configure == nil {
		return SlashResult{Name: name, StatusMessage: "skin: configuration unavailable"}
	}
	result, err := configure(Request{Name: name, SessionID: sessionID})
	if err != nil {
		return SlashResult{Name: name, Err: err, StatusMessage: "skin: " + err.Error()}
	}
	if name == "" {
		line := "skin: " + DisplayName(result.Name)
		return SlashResult{Name: name, Body: line, StatusMessage: line}
	}
	accepted := strings.TrimSpace(result.Name)
	if accepted == "" {
		accepted = name
	}
	return SlashResult{Name: name, AcceptedName: accepted, Apply: true}
}

func SlashName(input string) string {
	trimmed := strings.TrimSpace(input)
	if trimmed == "" {
		return ""
	}
	_, rest, ok := strings.Cut(trimmed, " ")
	if !ok {
		return ""
	}
	return strings.TrimSpace(rest)
}

func DisplayName(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		return "default"
	}
	return name
}

package skin

import (
	"errors"
	"testing"
)

func TestHandleSlashStatusAndApply(t *testing.T) {
	var got Request
	status := HandleSlash("/skin", "sess-skin", func(req Request) (Result, error) {
		got = req
		return Result{Name: "poseidon"}, nil
	})
	if got != (Request{SessionID: "sess-skin"}) {
		t.Fatalf("status request = %#v, want empty name/session", got)
	}
	if status.Apply || status.Body != "skin: poseidon" || status.StatusMessage != "skin: poseidon" {
		t.Fatalf("status result = %#v, want display-only poseidon", status)
	}
	apply := HandleSlash("/skin dracula", "sess-skin", func(req Request) (Result, error) {
		got = req
		return Result{Name: "dark"}, nil
	})
	if got != (Request{Name: "dracula", SessionID: "sess-skin"}) {
		t.Fatalf("apply request = %#v, want requested name/session", got)
	}
	if !apply.Apply || apply.AcceptedName != "dark" {
		t.Fatalf("apply result = %#v, want accepted dark", apply)
	}
}

func TestHandleSlashUnavailableAndError(t *testing.T) {
	if got := HandleSlash("/skin", "sess", nil).StatusMessage; got != "skin: configuration unavailable" {
		t.Fatalf("nil config status = %q, want unavailable", got)
	}
	errored := HandleSlash("/skin", "sess", func(Request) (Result, error) {
		return Result{}, errors.New("config locked")
	})
	if errored.Err == nil || errored.StatusMessage != "skin: config locked" {
		t.Fatalf("error result = %#v, want config error", errored)
	}
}

func TestSlashName(t *testing.T) {
	if got := SlashName("/skin ocean blue"); got != "ocean blue" {
		t.Fatalf("SlashName = %q, want full arg tail", got)
	}
	if got := SlashName("/skin"); got != "" {
		t.Fatalf("SlashName without arg = %q, want empty", got)
	}
}

func TestDisplayName(t *testing.T) {
	if got := DisplayName("  "); got != "default" {
		t.Fatalf("DisplayName empty = %q, want default", got)
	}
	if got := DisplayName(" poseidon "); got != "poseidon" {
		t.Fatalf("DisplayName trimmed = %q", got)
	}
}

package skin_test

import (
	"strings"
	"testing"

	tui "github.com/TrebuchetDynamics/gormes-agent/internal/tui"
)

func TestHermesSkin_DefaultTokens(t *testing.T) {
	skin := tui.DefaultHermesSkin()

	if skin.PromptSymbol != "❯ " {
		t.Fatalf("PromptSymbol = %q, want Hermes default prompt", skin.PromptSymbol)
	}
	if skin.ResponseLabel == "" || !strings.Contains(skin.ResponseLabel, "Gormes") {
		t.Fatalf("ResponseLabel = %q, want Gormes response label in Hermes-style chrome", skin.ResponseLabel)
	}
	if strings.Contains(skin.ResponseLabel, "Hermes") {
		t.Fatalf("ResponseLabel = %q, must not expose upstream Hermes product label", skin.ResponseLabel)
	}
	if skin.Colors.InputRule != "#CD7F32" {
		t.Fatalf("InputRule color = %q, want Hermes bronze", skin.Colors.InputRule)
	}

	wantStatus := map[string]string{
		"background": "#1a1a2e",
		"text":       "#C0C0C0",
		"strong":     "#FFD700",
		"dim":        "#8B8682",
	}
	gotStatus := map[string]string{
		"background": skin.Colors.StatusBarBackground,
		"text":       skin.Colors.StatusBarText,
		"strong":     skin.Colors.StatusBarStrong,
		"dim":        skin.Colors.StatusBarDim,
	}
	for name, want := range wantStatus {
		if got := gotStatus[name]; got != want {
			t.Fatalf("status %s color = %q, want %q", name, got, want)
		}
	}
}

func TestHermesSkin_MinimalChromeThreshold(t *testing.T) {
	skin := tui.DefaultHermesSkin()

	for _, tc := range []struct {
		width int
		want  bool
	}{
		{width: 0, want: true},
		{width: 63, want: true},
		{width: 64, want: false},
		{width: 120, want: false},
	} {
		if got := skin.UseMinimalChrome(tc.width); got != tc.want {
			t.Fatalf("UseMinimalChrome(%d) = %v, want %v", tc.width, got, tc.want)
		}
	}
}

func TestHermesSkin_ProfilePromptPrefix(t *testing.T) {
	skin := tui.DefaultHermesSkin()

	prompt, suffix := skin.PromptSymbols("research")
	if prompt != "research ❯ " {
		t.Fatalf("profile prompt = %q, want profile-prefixed Hermes prompt", prompt)
	}
	if suffix != "❯ " {
		t.Fatalf("state suffix = %q, want unchanged Hermes arrow suffix", suffix)
	}

	defaultPrompt, defaultSuffix := skin.PromptSymbols("default")
	if defaultPrompt != "❯ " || defaultSuffix != "❯ " {
		t.Fatalf("default profile prompt/suffix = %q/%q, want unprefixed Hermes arrow", defaultPrompt, defaultSuffix)
	}
}

func TestHermesSkin_BannerColors(t *testing.T) {
	skin := tui.DefaultHermesSkin()

	wantBanner := map[string]string{
		"border": "#CD7F32",
		"title":  "#FFD700",
		"accent": "#FFBF00",
		"dim":    "#B8860B",
		"text":   "#FFF8DC",
